import tailwindcss from '@tailwindcss/vite';
import react from '@vitejs/plugin-react';
import { defineConfig } from 'vite';

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss()],
});

import {
  coverageConfigDefaults,
  defineConfig,
  mergeConfig,
} from 'vitest/config';
import viteConfig from './vite.config';

export default mergeConfig(
  viteConfig,
  defineConfig({
    test: {
      globals: true,
      environment: 'jsdom',
      setupFiles: ['./vitest.setup.ts'],
      coverage: {
        provider: 'v8',
        reporter: ['text', 'json', 'html'],
        enabled: false,
        exclude: [
          ...coverageConfigDefaults.exclude,
          '**/.storybook/**',
          // This pattern must align with the `stories` property of `.storybook/main.ts`.
          '**/*.stories.*',
          // This pattern must align with the output directory of `storybook build`.
          '**/storybook-static/**',
        ],
      },
    },
  })
);

import { configDefaults, defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    name: 'frey-ui',
    environment: 'jsdom',
    globals: true,
    setupFiles: ['./vitest.setup.ts'],
    include: ['src/**/*.test.ts', 'src/**/*.test.tsx'],
    reporters: ['default', 'junit'],
    outputFile: {
      junit: './test-report.junit.xml',
    },
    coverage: {
      reporter: ['text', 'json', 'html', 'lcov'],
      reportsDirectory: './coverage',
      thresholds: {
        lines: 100,
        functions: 100,
        statements: 100,
        branches: 100,
      },
      exclude: [
        'src/index.ts',
        'src/types/**',
        'src/**/*.module.css',
        '**/*.mdx',
        '**/*.story.*',
        '**/*.stories.*',
        ...(configDefaults.coverage.exclude || []),
      ],
    },
  },
});

import crypto from 'node:crypto';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import commonjs from '@rollup/plugin-commonjs';
import resolve from '@rollup/plugin-node-resolve';
import typescript from '@rollup/plugin-typescript';
import MagicString from 'magic-string';
import postcss from 'postcss';
import postcssModules from 'postcss-modules';
import { defineConfig } from 'rollup';
import dts from 'rollup-plugin-dts';
import external from 'rollup-plugin-peer-deps-external';
import typescriptEngine from 'typescript';

const packageJson = JSON.parse(readFileSync('./package.json'));
const externalPackages = [
  ...Object.keys(packageJson.dependencies || {}),
  ...Object.keys(packageJson.peerDependencies || {}),
  'react/jsx-runtime',
];

function toPosixPath(filePath) {
  return filePath.split(path.sep).join('/');
}

function normalizeSourcemapSourcePath(sourcePath) {
  return sourcePath
    .replaceAll('\\', '/')
    .replace(/^\.\.\/\.\.\/\.\.\/\.\.\/src\//, '../../../src/');
}

function prependAfterDirectivePrologue(code, statement) {
  const magicString = new MagicString(code);
  const directiveRegex = /^(?:[ \t]*['"][^'"\r\n]+['"];[ \t]*(?:\r?\n|$))+/;
  const directiveMatch = code.match(directiveRegex);
  const insertIndex = directiveMatch ? directiveMatch[0].length : 0;

  magicString.appendLeft(insertIndex, `${statement}\n`);

  return {
    code: magicString.toString(),
    map: magicString.generateMap({ hires: true }),
  };
}

function cssModulesPlugin() {
  return {
    name: 'css-modules',
    async transform(code, id) {
      const sourceId = id.split('?')[0];
      if (!sourceId.endsWith('.css')) return null;

      const isTheme = sourceId.endsWith('theme.css');
      let classNames = {};

      const plugins = [];
      if (!isTheme) {
        plugins.push(
          postcssModules({
            generateScopedName: (name, filename) => {
              const hash = crypto
                .createHash('sha256')
                .update(filename + name)
                .digest('hex')
                .substring(0, 8);
              return `${name}_${hash}`;
            },
            getJSON: (_, json) => {
              classNames = json;
            },
          })
        );
      }

      const result = await postcss(plugins).process(code, {
        from: sourceId,
        to: sourceId,
      });

      const relativePath = path.relative(path.resolve('./src'), sourceId);
      const outputCssPath = isTheme
        ? relativePath
        : relativePath.replace('.module.css', '.css');
      const normalizedOutputCssPath = toPosixPath(outputCssPath);

      this.emitFile({
        type: 'asset',
        fileName: `cjs/${normalizedOutputCssPath}`,
        source: result.css,
      });
      this.emitFile({
        type: 'asset',
        fileName: `esm/${normalizedOutputCssPath}`,
        source: result.css,
      });

      if (isTheme) {
        return { code: '', map: { mappings: '' } };
      }

      return {
        code: `export default ${JSON.stringify(classNames)};`,
        map: { mappings: '' },
      };
    },

    renderChunk(code, chunk, options) {
      if (!chunk.facadeModuleId?.endsWith('.css')) {
        return null;
      }

      const isTheme = chunk.facadeModuleId.endsWith('theme.css');
      const outputCssName = isTheme
        ? 'theme.css'
        : path.basename(chunk.facadeModuleId).replace('.module.css', '.css');
      const cssSideEffect =
        options.format === 'cjs'
          ? `require('./${outputCssName}');`
          : `import './${outputCssName}';`;

      return prependAfterDirectivePrologue(code, cssSideEffect);
    },
  };
}

function normalizeSourcemapPathsPlugin() {
  return {
    name: 'normalize-sourcemap-paths',
    generateBundle(_outputOptions, bundle) {
      for (const chunkOrAsset of Object.values(bundle)) {
        if (chunkOrAsset.type !== 'chunk' || !chunkOrAsset.map?.sources)
          continue;

        chunkOrAsset.map.sources = chunkOrAsset.map.sources.map(
          normalizeSourcemapSourcePath
        );
      }
    },
  };
}

export default defineConfig([
  {
    input: './src/index.ts',
    output: [
      {
        dir: 'dist',
        format: 'cjs',
        sourcemap: true,
        sourcemapPathTransform: (relativeSourcePath) => {
          return normalizeSourcemapSourcePath(relativeSourcePath);
        },
        exports: 'named',
        preserveModules: true,
        preserveModulesRoot: 'src',
        entryFileNames: 'cjs/[name].cjs',
        chunkFileNames: 'cjs/[name]-[hash].cjs',
        name: packageJson.name,
        banner: "'use client';",
      },
      {
        dir: 'dist',
        format: 'es',
        exports: 'named',
        sourcemap: true,
        sourcemapPathTransform: (relativeSourcePath) => {
          return normalizeSourcemapSourcePath(relativeSourcePath);
        },
        preserveModules: true,
        preserveModulesRoot: 'src',
        entryFileNames: 'esm/[name].mjs',
        chunkFileNames: 'esm/[name]-[hash].mjs',
        banner: "'use client';",
      },
    ],
    external: externalPackages,
    plugins: [
      external({ includeDependencies: true }),
      resolve(),
      commonjs(),
      cssModulesPlugin(),
      typescript({
        tsconfig: './tsconfig.lib.json',
        typescript: typescriptEngine,
        sourceMap: true,
        exclude: [
          'coverage',
          '.storybook',
          'storybook-static',
          'config',
          'dist',
          'node_modules/**',
          '*.cjs',
          '*.mjs',
          '**/__snapshots__/*',
          '**/__tests__',
          '**/*.test.js+(|x)',
          '**/*.test.ts+(|x)',
          '**/*.mdx',
          '**/*.story.ts+(|x)',
          '**/*.story.js+(|x)',
          '**/*.stories.ts+(|x)',
          '**/*.stories.js+(|x)',
          'setupTests.ts',
          'vitest.config.ts',
        ],
      }),
      normalizeSourcemapPathsPlugin(),
    ],
  },
  {
    input: 'dist/types/src/index.d.ts',
    output: [{ file: 'dist/index.d.ts', format: 'esm' }],
    external: [/\.(sc|sa|c)ss$/],
    plugins: [dts()],
  },
]);

import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');
const require = createRequire(import.meta.url);

let cachedTypescript;

function getTypescript() {
  if (cachedTypescript) {
    return cachedTypescript;
  }

  const resolvedPath = require.resolve('typescript', {
    paths: [path.resolve(__dirname, '../apps/storybook')],
  });

  cachedTypescript = require(resolvedPath);
  return cachedTypescript;
}

function unwrapExpression(expression, ts) {
  let current = expression;

  while (
    ts.isSatisfiesExpression(current) ||
    ts.isAsExpression(current) ||
    ts.isParenthesizedExpression(current)
  ) {
    current = current.expression;
  }

  return current;
}

function getPropertyName(node, ts) {
  if (ts.isIdentifier(node.name) || ts.isStringLiteral(node.name)) {
    return node.name.text;
  }

  if (ts.isNumericLiteral(node.name)) {
    return node.name.text;
  }

  return null;
}

function getStoryComponentName(filePath) {
  return path.basename(path.dirname(filePath));
}

function getObjectLiteralProperty(node, propertyName, ts) {
  for (const property of node.properties) {
    if (
      !ts.isPropertyAssignment(property) &&
      !ts.isShorthandPropertyAssignment(property)
    ) {
      continue;
    }

    if (getPropertyName(property, ts) === propertyName) {
      return property;
    }
  }

  return null;
}

function getObjectLiteralValue(node, propertyName, ts) {
  const property = getObjectLiteralProperty(node, propertyName, ts);

  if (!property || ts.isShorthandPropertyAssignment(property)) {
    return null;
  }

  const value = unwrapExpression(property.initializer, ts);
  return ts.isObjectLiteralExpression(value) ? value : null;
}

function hasNestedSummary(node, nestedKey, ts) {
  const tableObject = getObjectLiteralValue(node, 'table', ts);

  if (!tableObject) {
    return false;
  }

  const nestedObject = getObjectLiteralValue(tableObject, nestedKey, ts);

  if (!nestedObject) {
    return false;
  }

  return getObjectLiteralProperty(nestedObject, 'summary', ts) !== null;
}

function isDisabledEntry(node, ts) {
  const tableObject = getObjectLiteralValue(node, 'table', ts);

  if (!tableObject) {
    return false;
  }

  const disableProperty = getObjectLiteralProperty(tableObject, 'disable', ts);

  if (!disableProperty || ts.isShorthandPropertyAssignment(disableProperty)) {
    return false;
  }

  return (
    unwrapExpression(disableProperty.initializer, ts).kind ===
    ts.SyntaxKind.TrueKeyword
  );
}

function getImportedNamesFromFreyUi(sourceFile, ts) {
  const imports = [];

  for (const statement of sourceFile.statements) {
    if (
      !ts.isImportDeclaration(statement) ||
      !ts.isStringLiteral(statement.moduleSpecifier) ||
      statement.moduleSpecifier.text !== 'frey-ui'
    ) {
      continue;
    }

    const importClause = statement.importClause;

    if (
      !importClause?.namedBindings ||
      !ts.isNamedImports(importClause.namedBindings)
    ) {
      continue;
    }

    for (const element of importClause.namedBindings.elements) {
      imports.push(element.name.text);
    }
  }

  return imports;
}

function findTypeDeclaration(sourceFile, typeName, ts) {
  for (const statement of sourceFile.statements) {
    if (
      (ts.isTypeAliasDeclaration(statement) ||
        ts.isInterfaceDeclaration(statement)) &&
      statement.name.text === typeName
    ) {
      return statement;
    }
  }

  return null;
}

function collectExplicitPropsFromDeclaration(
  declaration,
  sourceFile,
  ts,
  visited = new Set()
) {
  if (ts.isInterfaceDeclaration(declaration)) {
    return collectExplicitPropsFromMembers(
      declaration.members,
      sourceFile,
      ts,
      visited
    );
  }

  return collectExplicitPropsFromTypeNode(
    declaration.type,
    sourceFile,
    ts,
    visited
  );
}

function collectExplicitPropsFromMembers(
  members,
  sourceFile,
  ts,
  visited = new Set()
) {
  const props = new Set();

  for (const member of members) {
    if (!ts.isPropertySignature(member)) {
      continue;
    }

    const name = getPropertyName(member, ts);

    if (name) {
      props.add(name);
    }
  }

  return props;
}

function collectExplicitPropsFromTypeNode(
  typeNode,
  sourceFile,
  ts,
  visited = new Set()
) {
  const props = new Set();

  if (!typeNode) {
    return props;
  }

  const current = unwrapExpression(typeNode, ts);

  if (ts.isTypeLiteralNode(current)) {
    return collectExplicitPropsFromMembers(
      current.members,
      sourceFile,
      ts,
      visited
    );
  }

  if (ts.isIntersectionTypeNode(current)) {
    for (const typePart of current.types) {
      for (const prop of collectExplicitPropsFromTypeNode(
        typePart,
        sourceFile,
        ts,
        visited
      )) {
        props.add(prop);
      }
    }

    return props;
  }

  if (ts.isTypeReferenceNode(current) && ts.isIdentifier(current.typeName)) {
    const referenceName = current.typeName.text;

    if (visited.has(referenceName)) {
      return props;
    }

    visited.add(referenceName);

    const declaration = findTypeDeclaration(sourceFile, referenceName, ts);

    if (declaration) {
      for (const prop of collectExplicitPropsFromDeclaration(
        declaration,
        sourceFile,
        ts,
        visited
      )) {
        props.add(prop);
      }
    }
  }

  return props;
}

function getComponentSourceFiles(filePath, ts) {
  const componentName = getStoryComponentName(filePath);
  const componentDir = path.join(
    rootDir,
    'packages',
    'frey-ui',
    'src',
    componentName
  );

  if (!fs.existsSync(componentDir)) {
    return [];
  }

  return fs
    .readdirSync(componentDir)
    .filter(
      (entryName) =>
        (entryName.endsWith('.ts') || entryName.endsWith('.tsx')) &&
        !entryName.includes('.test.') &&
        !entryName.includes('.stories.')
    )
    .map((entryName) => path.join(componentDir, entryName))
    .map((componentPath) =>
      ts.createSourceFile(
        componentPath,
        fs.readFileSync(componentPath, 'utf8'),
        ts.ScriptTarget.Latest,
        true,
        componentPath.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS
      )
    );
}

function resolveDeclarationInComponentFiles(
  componentSourceFiles,
  typeName,
  ts
) {
  for (const sourceFile of componentSourceFiles) {
    const declaration = findTypeDeclaration(sourceFile, typeName, ts);

    if (declaration) {
      return { declaration, sourceFile };
    }
  }

  return null;
}

function resolveExplicitPropNames(filePath, storySourceFile, ts) {
  const importedNames = getImportedNamesFromFreyUi(storySourceFile, ts);

  if (importedNames.length === 0) {
    return [];
  }

  const componentSourceFiles = getComponentSourceFiles(filePath, ts);

  if (componentSourceFiles.length === 0) {
    return [];
  }

  const candidateTypeNames = [
    `${getStoryComponentName(filePath)}Props`,
    ...importedNames.filter((name) => name.endsWith('Props')),
  ];
  const uniqueCandidateTypeNames = [...new Set(candidateTypeNames)];

  for (const typeName of uniqueCandidateTypeNames) {
    const match = resolveDeclarationInComponentFiles(
      componentSourceFiles,
      typeName,
      ts
    );

    if (!match) {
      continue;
    }

    return [
      ...collectExplicitPropsFromDeclaration(
        match.declaration,
        match.sourceFile,
        ts
      ),
    ];
  }

  return [];
}

function findMetaObject(sourceFile, ts) {
  for (const statement of sourceFile.statements) {
    if (!ts.isVariableStatement(statement)) {
      continue;
    }

    for (const declaration of statement.declarationList.declarations) {
      if (
        !ts.isIdentifier(declaration.name) ||
        declaration.name.text !== 'meta'
      ) {
        continue;
      }

      if (!declaration.initializer) {
        continue;
      }

      const initializer = unwrapExpression(declaration.initializer, ts);

      if (ts.isObjectLiteralExpression(initializer)) {
        return initializer;
      }
    }
  }

  return null;
}

export function collectStoryDocsIssues({ filePath, sourceText }) {
  const ts = getTypescript();
  const sourceFile = ts.createSourceFile(
    filePath,
    sourceText,
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.TSX
  );
  const metaObject = findMetaObject(sourceFile, ts);

  if (!metaObject) {
    return ['Missing meta object literal.'];
  }

  const argTypesObject = getObjectLiteralValue(metaObject, 'argTypes', ts);

  if (!argTypesObject) {
    return ['Missing meta.argTypes block.'];
  }

  const issues = [];
  const entryMap = new Map();

  for (const property of argTypesObject.properties) {
    if (!ts.isPropertyAssignment(property)) {
      continue;
    }

    const entryName = getPropertyName(property, ts);

    if (!entryName) {
      continue;
    }

    const entryValue = unwrapExpression(property.initializer, ts);

    if (!ts.isObjectLiteralExpression(entryValue)) {
      issues.push(`ArgTypes entry '${entryName}' must be an object literal.`);
      continue;
    }

    entryMap.set(entryName, entryValue);

    if (isDisabledEntry(entryValue, ts)) {
      continue;
    }

    if (getObjectLiteralProperty(entryValue, 'description', ts) === null) {
      issues.push(
        `Incomplete argTypes entry '${entryName}': missing description.`
      );
    }

    if (!hasNestedSummary(entryValue, 'type', ts)) {
      issues.push(
        `Incomplete argTypes entry '${entryName}': missing table.type.summary.`
      );
    }

    if (!hasNestedSummary(entryValue, 'defaultValue', ts)) {
      issues.push(
        `Incomplete argTypes entry '${entryName}': missing table.defaultValue.summary.`
      );
    }

    if (
      getObjectLiteralProperty(entryValue, 'control', ts) === null &&
      getObjectLiteralProperty(entryValue, 'action', ts) === null
    ) {
      issues.push(
        `Incomplete argTypes entry '${entryName}': missing control or action.`
      );
    }
  }

  const explicitPropNames = resolveExplicitPropNames(filePath, sourceFile, ts);

  for (const propName of explicitPropNames) {
    const entryValue = entryMap.get(propName);

    if (!entryValue || isDisabledEntry(entryValue, ts)) {
      issues.push(
        `Missing visible argTypes entry for exported prop '${propName}'.`
      );
    }
  }

  return issues;
}

export function collectStoryDocsIssuesFromFile(filePath) {
  return collectStoryDocsIssues({
    filePath,
    sourceText: fs.readFileSync(filePath, 'utf8'),
  });
}

import { defineConfig, devices } from '@playwright/test';

type EnvMap = Record<string, string | undefined>;

const env = (
  globalThis as {
    process?: { env?: EnvMap };
  }
).process?.env;

const PORT = Number.parseInt(env?.PLAYWRIGHT_STORYBOOK_PORT ?? '6006', 10);
const localBaseURL = `http://127.0.0.1:${PORT}`;
const hasCustomBaseURL = Boolean(env?.PLAYWRIGHT_BASE_URL);
const baseURL = env?.PLAYWRIGHT_BASE_URL ?? localBaseURL;
const storybookStaticDir = '../storybook/storybook-static';
const serveCommand = `pnpm exec serve -c $PWD/serve.json -l tcp://127.0.0.1:${PORT} ${storybookStaticDir}`;

export default defineConfig({
  testDir: './tests',
  timeout: 45_000,
  fullyParallel: true,
  forbidOnly: Boolean(env?.CI),
  retries: env?.CI ? 2 : 0,
  workers: env?.CI ? 1 : undefined,
  reporter: [['list'], ['html', { open: 'never' }]],
  use: {
    baseURL,
    trace: 'retain-on-failure',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
  webServer: hasCustomBaseURL
    ? undefined
    : {
        command: serveCommand,
        url: localBaseURL,
        reuseExistingServer: !env?.CI,
        timeout: 120_000,
      },
});

